@section('scripts')<script>for(const kind of ['department','position']){const search=document.querySelector('[data-org-search="'+kind+'"]');const status=document.querySelector('[data-org-status="'+kind+'"]');const items=document.querySelectorAll('[data-org-item="'+kind+'"]');const filter=()=>{const term=search.value.trim().toLowerCase();for(const item of items)item.hidden=!!((term&&!item.dataset.orgText.includes(term))||(status.value&&item.dataset.orgState!==status.value));};search.addEventListener('input',filter);status.addEventListener('change',filter);}</script>@endsection
